const staticData = $getWorkflowStaticData('global');
const now = new Date();
const runStartedAt = now.toISOString();
const beforeEpoch = Math.floor(now.getTime() / 1000);

let lastRun = staticData.lastRun;
let windowStartDate;
if (lastRun && typeof lastRun === 'string' && !isNaN(Date.parse(lastRun))) {
  windowStartDate = new Date(lastRun);
} else {
  windowStartDate = new Date(now.getTime() - 24 * 60 * 60 * 1000);
}

const windowStart = windowStartDate.toISOString();
const afterEpoch = Math.floor(windowStartDate.getTime() / 1000);

return [{
  json: {
    runStartedAt,
    afterEpoch,
    beforeEpoch,
    windowStart,
    windowEnd: runStartedAt
  }
}];

const items = $input.all();

function cleanName(n) {
  if (!n || typeof n !== 'string') return '';
  return n.trim().replace(/^["']+|["']+$/g, '').trim();
}

function parseSenderString(str) {
  if (!str || typeof str !== 'string') return '';
  let s = str.trim().replace(/^from:\s*/i, '');
  const match = s.match(/^(?:["']?(.*?)["']?\s*)?<([^>]+)>$/);
  if (match) {
    const name = cleanName(match[1]);
    const email = cleanName(match[2]);
    if (name) return name;
    if (email) return email;
  }
  return cleanName(s);
}

function getSender(msg) {
  if (!msg) return 'Unknown sender';

  // 1. Real Gmail shape & from.value[0]: object with value: [{ address, name }]
  if (msg.from && typeof msg.from === 'object') {
    const val = Array.isArray(msg.from.value) ? msg.from.value[0] : (msg.from.value || msg.from);
    if (val && typeof val === 'object') {
      const name = cleanName(val.name);
      const address = cleanName(val.address);
      if (name) return name;
      if (address) return address;
    }
    if (typeof msg.from.text === 'string' && msg.from.text.trim()) {
      const parsed = parseSenderString(msg.from.text);
      if (parsed) return parsed;
    }
  }

  // 2. "from" or "From" string
  if (typeof msg.from === 'string' && msg.from.trim()) {
    const parsed = parseSenderString(msg.from);
    if (parsed) return parsed;
  }
  if (typeof msg.From === 'string' && msg.From.trim()) {
    const parsed = parseSenderString(msg.From);
    if (parsed) return parsed;
  }

  // 3. From header in payload.headers (case-insensitive) or msg.headers
  const headers = msg.payload?.headers || msg.headers;
  if (Array.isArray(headers)) {
    const h = headers.find(item => item && item.name && item.name.toLowerCase() === 'from');
    if (h && typeof h.value === 'string') {
      const parsed = parseSenderString(h.value);
      if (parsed) return parsed;
    }
  } else if (headers && typeof headers === 'object') {
    for (const [k, v] of Object.entries(headers)) {
      if (k.toLowerCase() === 'from' && typeof v === 'string') {
        const parsed = parseSenderString(v);
        if (parsed) return parsed;
      }
    }
  }

  return 'Unknown sender';
}

function getHeader(msg, headerName) {
  if (typeof msg[headerName] === 'string') return msg[headerName];
  if (typeof msg[headerName.toLowerCase()] === 'string') return msg[headerName.toLowerCase()];
  const headers = msg.payload?.headers || msg.headers;
  if (Array.isArray(headers)) {
    const h = headers.find(item => item && item.name && item.name.toLowerCase() === headerName.toLowerCase());
    if (h && typeof h.value === 'string') return h.value;
  } else if (headers && typeof headers === 'object') {
    for (const [k, v] of Object.entries(headers)) {
      if (k.toLowerCase() === headerName.toLowerCase() && typeof v === 'string') {
        return v.replace(new RegExp(`^${headerName}:\\s*`, 'i'), '');
      }
    }
  }
  return '';
}

function getMessageDate(msg) {
  if (msg.date && !isNaN(Date.parse(msg.date))) {
    return new Date(msg.date);
  }
  if (msg.internalDate) {
    const epochMs = Number(msg.internalDate);
    if (!isNaN(epochMs)) return new Date(epochMs);
  }
  const dateHdr = getHeader(msg, 'Date');
  if (dateHdr && !isNaN(Date.parse(dateHdr))) {
    return new Date(dateHdr);
  }
  return new Date();
}

function countAttachments(msg) {
  let count = 0;
  function walkParts(parts) {
    if (!Array.isArray(parts)) return;
    for (const part of parts) {
      if (part.filename && typeof part.filename === 'string' && part.filename.trim() !== '') {
        count++;
      }
      if (part.parts) {
        walkParts(part.parts);
      }
    }
  }
  if (msg.payload?.parts) {
    walkParts(msg.payload.parts);
  } else if (msg.parts) {
    walkParts(msg.parts);
  } else if (msg.attachments && Array.isArray(msg.attachments)) {
    count += msg.attachments.length;
  }
  return count;
}

function extractText(msg) {
  if (msg.text && typeof msg.text === 'string' && msg.text.trim()) {
    return msg.text;
  }
  let bodyText = '';
  function findBody(parts) {
    if (!Array.isArray(parts)) return;
    for (const part of parts) {
      if (part.mimeType === 'text/plain' && part.body?.data) {
        try {
          const decoded = Buffer.from(part.body.data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
          if (decoded) bodyText += (bodyText ? '\n' : '') + decoded;
        } catch (e) {}
      } else if (part.mimeType === 'text/plain' && typeof part.body === 'string') {
        bodyText += (bodyText ? '\n' : '') + part.body;
      }
      if (part.parts) {
        findBody(part.parts);
      }
    }
  }
  if (msg.payload?.parts) {
    findBody(msg.payload.parts);
  } else if (msg.parts) {
    findBody(msg.parts);
  }
  if (!bodyText && msg.payload?.body?.data) {
    try {
      bodyText = Buffer.from(msg.payload.body.data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
    } catch (e) {}
  }
  if (!bodyText && msg.snippet) {
    bodyText = msg.snippet;
  }
  if (!bodyText && msg.html) {
    bodyText = msg.html;
  }
  return bodyText || '';
}

function extractLabels(msg) {
  if (Array.isArray(msg.labelIds)) return msg.labelIds;
  if (Array.isArray(msg.labels)) {
    return msg.labels.map(l => (typeof l === 'string' ? l : l.name || l.id));
  }
  return [];
}

const threadMap = new Map();
for (const item of items) {
  const msg = item.json;
  if (!msg || (!msg.id && !msg.threadId)) continue;
  const threadId = msg.threadId || msg.id;
  if (!threadMap.has(threadId)) {
    threadMap.set(threadId, []);
  }
  threadMap.get(threadId).push(msg);
}

const outputThreads = [];
for (const [threadId, messages] of threadMap.entries()) {
  messages.sort((a, b) => getMessageDate(a).getTime() - getMessageDate(b).getTime());
  const newestMsg = messages[messages.length - 1];
  const earlierMsgs = messages.slice(0, -1);

  const subject = (typeof newestMsg.subject === 'string' && newestMsg.subject.trim())
    ? newestMsg.subject.trim()
    : (getHeader(newestMsg, 'Subject') || newestMsg.Subject || '(No subject)');
  const from = getSender(newestMsg);
  const labelIds = extractLabels(newestMsg);
  const receivedAt = getMessageDate(newestMsg).toISOString();
  const messageCount = messages.length;
  const replies = messageCount - 1;
  const files = messages.reduce((sum, m) => sum + countAttachments(m), 0);
  const gmailLink = 'https://mail.google.com/mail/u/0/#all/' + threadId;
  const latest = extractText(newestMsg);
  const earlier = earlierMsgs.map(extractText).filter(t => t.trim().length > 0).join('\n---\n');

  outputThreads.push({
    json: {
      threadId,
      subject,
      from,
      labelIds,
      receivedAt,
      messageCount,
      replies,
      files,
      gmailLink,
      latest,
      earlier
    }
  });
}

return outputThreads;

function stripHtmlAndDecode(str) {
  if (!str || typeof str !== 'string') return '';
  let text = str.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
                .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
                .replace(/<br\s*[\/]?>/gi, '\n')
                .replace(/<\/p>/gi, '\n')
                .replace(/<\/div>/gi, '\n')
                .replace(/<[^>]+>/g, ' ');
  text = text.replace(/&amp;/g, '&')
             .replace(/&lt;/g, '<')
             .replace(/&gt;/g, '>')
             .replace(/&quot;/g, '"')
             .replace(/&#39;|&apos;/g, "'")
             .replace(/&nbsp;/g, ' ')
             .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
             .replace(/&#([0-9]+);/g, (_, dec) => String.fromCharCode(parseInt(dec, 10)));
  return text;
}

function cleanMessageText(text) {
  if (!text || typeof text !== 'string') return '';
  let cleaned = stripHtmlAndDecode(text);
  const lines = cleaned.split(/\r?\n/);
  const resultLines = [];

  for (let line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('>')) continue;
    if (/^On\s+.+wrote:?$/i.test(trimmed)) continue;
    if (/^-+\s*(?:Original Message|Forwarded Message)\s*-+/i.test(trimmed)) continue;
    if (/^--\s*$/i.test(trimmed) || /^--\s+.+/i.test(trimmed)) break;
    if (/^Sent from my (?:iPhone|iPad|Galaxy|device|phone)/i.test(trimmed)) continue;
    if (/^Sent from Mail for Windows/i.test(trimmed)) continue;
    if (/^(?:To unsubscribe|Click here to unsubscribe|Unsubscribe|Manage preferences|You are receiving this email because)/i.test(trimmed)) continue;

    resultLines.push(line);
  }

  let combined = resultLines.join('\n');
  combined = combined.replace(/[ \t]+/g, ' ');
  combined = combined.replace(/\n\s*\n+/g, '\n');
  return combined.trim();
}

return $input.all().map(item => {
  const input = item.json;
  const cleanedLatest = cleanMessageText(input.latest || '').slice(0, 800);
  const cleanedEarlier = cleanMessageText(input.earlier || '').slice(0, 300);

  let text = cleanedLatest;
  if (cleanedEarlier && cleanedEarlier.length > 0) {
    text = cleanedLatest + ' | Earlier: ' + cleanedEarlier;
  }

  return {
    json: {
      threadId: input.threadId,
      subject: input.subject,
      from: input.from,
      labelIds: input.labelIds || [],
      receivedAt: input.receivedAt,
      messageCount: input.messageCount,
      replies: input.replies,
      files: input.files,
      gmailLink: input.gmailLink,
      text,
      ruleIgnore: false
    }
  };
});

return $input.all().map(item => {
  const labels = item.json.labelIds || [];
  const ruleIgnore = labels.includes('CATEGORY_PROMOTIONS') || labels.includes('CATEGORY_SOCIAL');
  return {
    json: {
      ...item.json,
      ruleIgnore
    }
  };
});

const allItems = $input.all();
const aiThreads = [];
const ruleIgnored = [];

for (const item of allItems) {
  const t = item.json;
  if (t.ruleIgnore) {
    ruleIgnored.push({
      threadId: t.threadId,
      subject: t.subject,
      from: t.from,
      receivedAt: t.receivedAt,
      messageCount: t.messageCount,
      replies: t.replies,
      files: t.files,
      gmailLink: t.gmailLink
    });
  } else {
    aiThreads.push(t);
  }
}

const numberedAiThreads = aiThreads.map((t, index) => ({
  id: index + 1,
  threadId: t.threadId,
  subject: t.subject,
  from: t.from,
  text: t.text,
  receivedAt: t.receivedAt,
  messageCount: t.messageCount,
  replies: t.replies,
  files: t.files,
  gmailLink: t.gmailLink
}));

const batches = [];
if (numberedAiThreads.length === 0) {
  batches.push({
    json: {
      batchNo: 1,
      threads: [],
      ruleIgnored: ruleIgnored
    }
  });
} else {
  const batchSize = 10;
  for (let i = 0; i < numberedAiThreads.length; i += batchSize) {
    const batchNo = Math.floor(i / batchSize) + 1;
    const batchThreads = numberedAiThreads.slice(i, i + batchSize);
    batches.push({
      json: {
        batchNo,
        threads: batchThreads,
        ruleIgnored: batchNo === 1 ? ruleIgnored : []
      }
    });
  }
}

return batches;

// Outputs 31 Gmail-shaped messages: 27 normal threads, 4 Promotions/Social
